/**
 * Helper to generate iCal / RFC-5545 string for 1-click export
 */
export function generateIcsCalendar(districtName: string, items: WasteCollectionItem[]): string {
  const pad = (n: number) => (n < 10 ? '0' + n : n);
  const now = new Date();
  const dtStamp = `${now.getUTCFullYear()}${pad(now.getUTCMonth() + 1)}${pad(now.getUTCDate())}T${pad(now.getUTCHours())}${pad(now.getUTCMinutes())}${pad(now.getUTCSeconds())}Z`;

  const eventsStr = items.map((item, idx) => {
    const [y, m, d] = item.date.split('-');
    const dtStart = `${y}${m}${d}`;
    const nextDay = new Date(parseInt(y), parseInt(m) - 1, parseInt(d) + 1);
    const dtEnd = `${nextDay.getFullYear()}${pad(nextDay.getMonth() + 1)}${pad(nextDay.getDate())}`;

    return [
      'BEGIN:VEVENT',
      `UID:winterberg-${districtName}-${item.date}-${item.binType}-${idx}@winterberg-verzeichnis.de`,
      `DTSTAMP:${dtStamp}`,
      `DTSTART;VALUE=DATE:${dtStart}`,
      `DTEND;VALUE=DATE:${dtEnd}`,
      `SUMMARY:${item.title} (59955 ${districtName})`,
      `DESCRIPTION:${item.notes || 'Abfuhrtermin laut Abfallkalender der Stadt Winterberg.'}`,
      `LOCATION:${districtName}, 59955 Winterberg`,
      'STATUS:CONFIRMED',
      'TRANSP:TRANSPARENT',
      'BEGIN:VALARM',
      'TRIGGER:-PT12H',
      'ACTION:DISPLAY',
      `DESCRIPTION:Erinnerung: Morgen ${item.title}`,
      'END:VALARM',
      'END:VEVENT'
    ].join('\r\n');
  }).join('\r\n');

  return [
    'BEGIN:VCALENDAR',
    'VERSION:2.0',
    'PRODID:-//Winterberg-Verzeichnis//Abfallkalender 2026//DE',
    'CALSCALE:GREGORIAN',
    'METHOD:PUBLISH',
    `X-WR-CALNAME:Abfallkalender 2026 - ${districtName}`,
    'X-WR-TIMEZONE:Europe/Berlin',
    eventsStr,
    'END:VCALENDAR'
  ].join('\r\n');
}
